use std::path::PathBuf;
use std::fs;
use std::time::Instant;
use clap::{Command, Arg, ArgAction};
use regex::Regex;
use serde::Serialize;
use chrono::Local;
use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LinkStyle {
    Github,
    Gitlab,
    Stash,
    Cgit,
}

impl LinkStyle {
    fn from_str(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "github" => Some(Self::Github),
            "gitlab" => Some(Self::Gitlab),
            "stash" => Some(Self::Stash),
            "cgit" => Some(Self::Cgit),
            _ => None,
        }
    }
}

#[derive(Debug, Serialize)]
struct JsonHeader {
    version: Option<String>,
    patch_version: bool,
    subtitle: Option<String>,
    date: String,
}

#[derive(Debug, Serialize)]
struct JsonCommit {
    component: Option<String>,
    subject: String,
    commit_link: String,
    closes: Option<Vec<String>>,
    breaks: Option<Vec<String>>,
}

#[derive(Debug, Serialize)]
struct JsonSection {
    title: String,
    commits: Vec<JsonCommit>,
}

#[derive(Debug, Serialize)]
struct JsonChangelog {
    header: JsonHeader,
    sections: Option<Vec<JsonSection>>,
}

#[derive(Debug, Clone)]
struct ParsedCommit {
    type_: String,
    component: Option<String>,
    subject: String,
    body: String,
    hash: String,
    short_hash: String,
    closes: Vec<String>,
    breaks: Vec<String>,
    is_breaking: bool,
}

fn parse_conventional(message: &str, hash: &str) -> Option<ParsedCommit> {
    let re = Regex::new(r"^(?P<type>\w+)(?:\((?P<scope>[^\)]+)\))?(?P<breaking>!)?:\s*(?P<subject>.+)").unwrap();
    let mut lines = message.lines();
    let first_line = lines.next().unwrap_or("").trim();
    if let Some(caps) = re.captures(first_line) {
        let type_ = caps.name("type").unwrap().as_str().to_string();
        let component = caps.name("scope").map(|m| m.as_str().to_string());
        let breaking = caps.name("breaking").is_some();
        let subject = caps.name("subject").unwrap().as_str().to_string();
        let body = lines.collect::<Vec<&str>>().join("\n");
        let mut is_breaking = breaking;
        let closes_re = Regex::new(r"(?i)(?:close|closes|closed|fix|fixes|fixed|resolve|resolves|resolved)\s+#?(\d+)").unwrap();
        let mut closes = Vec::new();
        for cap in closes_re.captures_iter(message) {
            if let Some(m) = cap.get(1) {
                closes.push(m.as_str().to_string());
            }
        }
        if body.contains("BREAKING CHANGE:") {
            is_breaking = true;
        }
        Some(ParsedCommit {
            type_,
            component,
            subject,
            body,
            hash: hash.to_string(),
            short_hash: if hash.len() >= 7 { hash[..7].to_string() } else { hash.to_string() },
            closes,
            breaks: Vec::new(),
            is_breaking,
        })
    } else {
        None
    }
}

fn generate_markdown(version: &Option<String>, subtitle: &Option<String>, date: &str, sections: &Vec<(String, Vec<ParsedCommit>)>, repo_url: &Option<String>, link_style: &LinkStyle) -> String {
    let version_str = version.as_deref().unwrap_or("");
    let subtitle_str = subtitle.as_deref().unwrap_or("");
    let mut s = String::new();
    s.push_str(&format!("<a name=\"{}\"></a>\n", version_str));
    s.push_str(&format!("## {} {} ({})\n", version_str, subtitle_str, date));
    s.push_str("\n");
    if sections.is_empty() {
        s.push_str("\n\n\n");
        return s;
    }
    s.push_str("\n");
    for (title, commits) in sections {
        s.push_str(&format!("#### {}\n\n", title));
        for commit in commits {
            let mut line = String::from("* ");
            if let Some(comp) = &commit.component {
                line.push_str(&format!("**{}**: ", comp));
            }
            line.push_str(&commit.subject);
            let short = if commit.hash.len() >= 7 { &commit.hash[..7] } else { &commit.hash };
            let commit_url = generate_commit_link(repo_url, &commit.hash, link_style);
            line.push_str(&format!(" ([{}]({}))", short, commit_url));
            if !commit.closes.is_empty() {
                for issue in &commit.closes {
                    let issue_url = generate_issue_link(repo_url, issue, link_style);
                    line.push_str(&format!(", closes [#{}]({})", issue, issue_url));
                }
            }
            s.push_str(&line);
            s.push_str("\n");
        }
        s.push_str("\n");
    }
    s
}

fn generate_commit_link(repo_url: &Option<String>, hash: &str, style: &LinkStyle) -> String {
    let short = if hash.len() >= 7 { &hash[..7] } else { hash };
    if let Some(repo) = repo_url {
        let repo = repo.trim_end_matches('/');
        match style {
            LinkStyle::Github => format!("{}/commit/{}", repo, short),
            LinkStyle::Gitlab => format!("{}/commit/{}", repo, short),
            LinkStyle::Stash => format!("{}/commits/{}", repo, short),
            LinkStyle::Cgit => format!("{}/commit/?id={}", repo, hash),
        }
    } else {
        short.to_string()
    }
}

fn generate_issue_link(repo_url: &Option<String>, issue: &str, _style: &LinkStyle) -> String {
    if let Some(repo) = repo_url {
        let repo = repo.trim_end_matches('/');
        format!("{}/issues/{}", repo, issue)
    } else {
        format!("#{}", issue)
    }
}

