#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LinkStyle {
    Github,
    Gitlab,
    Stash,
    Cgit,
}

impl LinkStyle {
    fn from_str(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "github" => Some(Self::Github),
            "gitlab" => Some(Self::Gitlab),
            "stash" => Some(Self::Stash),
            "cgit" => Some(Self::Cgit),
            _ => None,
        }
    }
}

#[derive(Debug, Serialize)]
struct JsonHeader {
    version: Option<String>,
    patch_version: bool,
    subtitle: Option<String>,
    date: String,
}

#[derive(Debug, Serialize)]
struct JsonCommit {
    component: Option<String>,
    subject: String,
    commit_link: String,
    closes: Option<Vec<String>>,
    breaks: Option<Vec<String>>,
}

#[derive(Debug, Serialize)]
struct JsonSection {
    title: String,
    commits: Vec<JsonCommit>,
}

#[derive(Debug, Serialize)]
struct JsonChangelog {
    header: JsonHeader,
    sections: Option<Vec<JsonSection>>,
}

#[derive(Debug, Clone)]
struct ParsedCommit {
    type_: String,
    component: Option<String>,
    subject: String,
    body: String,
    hash: String,
    short_hash: String,
    closes: Vec<String>,
    breaks: Vec<String>,
    is_breaking: bool,
}

fn parse_conventional(message: &str, hash: &str) -> Option<ParsedCommit> {
    let re = Regex::new(r"^(?P<type>\w+)(?:\((?P<scope>[^\)]+)\))?(?P<breaking>!)?:\s*(?P<subject>.+)").unwrap();
    let mut lines = message.lines();
    let first_line = lines.next().unwrap_or("").trim();
    if let Some(caps) = re.captures(first_line) {
        let type_ = caps.name("type").unwrap().as_str().to_string();
        let component = caps.name("scope").map(|m| m.as_str().to_string());
        let breaking = caps.name("breaking").is_some();
        let subject = caps.name("subject").unwrap().as_str().to_string();
        let body = lines.collect::<Vec<&str>>().join("\n");
        let mut is_breaking = breaking;
        let closes_re = Regex::new(r"(?i)(?:close|closes|closed|fix|fixes|fixed|resolve|resolves|resolved)\s+#?(\d+)").unwrap();
        let mut closes = Vec::new();
        for cap in closes_re.captures_iter(message) {
            if let Some(m) = cap.get(1) {
                closes.push(m.as_str().to_string());
            }
        }
        if body.contains("BREAKING CHANGE:") {
            is_breaking = true;
        }
        Some(ParsedCommit {
            type_,
            component,
            subject,
            body,
            hash: hash.to_string(),
            short_hash: if hash.len() >= 7 { hash[..7].to_string() } else { hash.to_string() },
            closes,
            breaks: Vec::new(),
            is_breaking,
        })
    } else {
        None
    }
}

fn generate_markdown(version: &Option<String>, subtitle: &Option<String>, date: &str, sections: &Vec<(String, Vec<ParsedCommit>)>, repo_url: &Option<String>, link_style: &LinkStyle) -> String {
    let version_str = version.as_deref().unwrap_or("");
    let subtitle_str = subtitle.as_deref().unwrap_or("");
    let mut s = String::new();
    s.push_str(&format!("<a name=\"{}\"></a>\n", version_str));
    s.push_str(&format!("## {} {} ({})\n", version_str, subtitle_str, date));
    s.push_str("\n");
    if sections.is_empty() {
        s.push_str("\n\n\n");
        return s;
    }
    s.push_str("\n");
    for (title, commits) in sections {
        s.push_str(&format!("#### {}\n\n", title));
        for commit in commits {
            let mut line = String::from("* ");
            if let Some(comp) = &commit.component {
                line.push_str(&format!("**{}**: ", comp));
            }
            line.push_str(&commit.subject);
            let short = if commit.hash.len() >= 7 { &commit.hash[..7] } else { &commit.hash };
            let commit_url = generate_commit_link(repo_url, &commit.hash, link_style);
            line.push_str(&format!(" ([{}]({}))", short, commit_url));
            if !commit.closes.is_empty() {
                for issue in &commit.closes {
                    let issue_url = generate_issue_link(repo_url, issue, link_style);
                    line.push_str(&format!(", closes [#{}]({})", issue, issue_url));
                }
            }
            s.push_str(&line);
            s.push_str("\n");
        }
        s.push_str("\n");
    }
    s
}

fn generate_commit_link(repo_url: &Option<String>, hash: &str, style: &LinkStyle) -> String {
    let short = if hash.len() >= 7 { &hash[..7] } else { hash };
    if let Some(repo) = repo_url {
        let repo = repo.trim_end_matches('/');
        match style {
            LinkStyle::Github => format!("{}/commit/{}", repo, short),
            LinkStyle::Gitlab => format!("{}/commit/{}", repo, short),
            LinkStyle::Stash => format!("{}/commits/{}", repo, short),
            LinkStyle::Cgit => format!("{}/commit/?id={}", repo, hash),
        }
    } else {
        short.to_string()
    }
}

fn generate_issue_link(repo_url: &Option<String>, issue: &str, _style: &LinkStyle) -> String {
    if let Some(repo) = repo_url {
        let repo = repo.trim_end_matches('/');
        format!("{}/issues/{}", repo, issue)
    } else {
        format!("#{}", issue)
    }
}

fn main() {
    let start = Instant::now();

    // Custom handling for --version and --help before clap, to match exact output
    let args: Vec<String> = std::env::args().collect();
    // Check for version
    for arg in &args {
        if arg == "--version" || arg == "-V" {
            println!("clog 0.10.0");
            return;
        }
    }
    // Check for help
    for arg in &args {
        if arg == "--help" || arg == "-h" {
            print_help();
            return;
        }
    }

    let cmd = Command::new("executable")
        .bin_name("executable")
        .version("0.10.0")
        .about("a conventional changelog for the rest of us")
        .disable_version_flag(true)
        .disable_help_flag(true)
        .after_help("If your .git directory is a child of your project directory (most common, such as /myproject/.git)\nAND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only\nneed to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you\ndon't need to use both.\n\nIf using the --config to specify a clog configuration TOML file NOT in the current working directory\n(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project\ndirectory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir.")
        .arg(Arg::new("repository").short('r').long("repository").value_name("URL").help("Repository used for generating commit and issue links (without the .git, e.g. https://github.com/thoughtram/clog)"))
        .arg(Arg::new("from").short('f').long("from").value_name("COMMIT").help("e.g. 12a8546"))
        .arg(Arg::new("format").short('T').long("format").value_name("STR").default_value("markdown").value_parser(["markdown", "json"]).help("The output format, defaults to markdown"))
        .arg(Arg::new("major").short('M').long("major").action(ArgAction::SetTrue).help("Increment major version by one (Sets minor and patch to 0)"))
        .arg(Arg::new("git-dir").short('g').long("git-dir").value_name("PATH").help("Local .git directory (defaults to \"$(pwd)/.git\")"))
        .arg(Arg::new("work-tree").short('w').long("work-tree").value_name("PATH").help("Local working tree of the git project (defaults to \"$(pwd)\")"))
        .arg(Arg::new("minor").short('m').long("minor").action(ArgAction::SetTrue).help("Increment minor version by one (Sets patch to 0)"))
        .arg(Arg::new("patch").short('p').long("patch").action(ArgAction::SetTrue).help("Increment patch version by one"))
        .arg(Arg::new("subtitle").short('s').long("subtitle").value_name("STR").help(""))
        .arg(Arg::new("to").short('t').long("to").value_name("COMMIT").default_value("HEAD").help("e.g. 8057684"))
        .arg(Arg::new("outfile").short('o').long("outfile").value_name("PATH").help("Where to write the changelog (Defaults to stdout when omitted)"))
        .arg(Arg::new("config").short('c').long("config").value_name("COMMIT").default_value(".clog.toml").help("The Clog Configuration TOML file to use"))
        .arg(Arg::new("infile").short('i').long("infile").value_name("PATH").help("A changelog to append to, but *NOT* write to (Useful in conjunction with --outfile)"))
        .arg(Arg::new("setversion").long("setversion").value_name("VER").help("e.g. 1.0.1"))
        .arg(Arg::new("from-latest-tag").short('F').long("from-latest-tag").action(ArgAction::SetTrue).help("use latest tag as start (instead of --from)"))
        .arg(Arg::new("link-style").short('l').long("link-style").value_name("STR").default_value("github").value_parser(["github", "gitlab", "stash", "cgit"]).help("The style of repository link to generate"))
        .arg(Arg::new("changelog").short('C').long("changelog").value_name("PATH").conflicts_with("outfile").conflicts_with("infile").help("A previous changelog to prepend new changes to (this is like using the same file for both --infile and --outfile and should not be used in conjunction with either)"))
        .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("Print help"))
        .arg(Arg::new("version").short('V').long("version").action(ArgAction::SetTrue).help("Print version"));

    let matches = cmd.clone().get_matches();

    if matches.get_flag("help") {
        print_help();
        return;
    }
    if matches.get_flag("version") {
        println!("clog 0.10.0");
        return;
    }

    let repository: Option<String> = matches.get_one::<String>("repository").cloned();
    let from_cli: Option<String> = matches.get_one::<String>("from").cloned();
    let format_cli: String = matches.get_one::<String>("format").unwrap().clone();
    let major = matches.get_flag("major");
    let git_dir_cli: Option<PathBuf> = matches.get_one::<String>("git-dir").map(|s| PathBuf::from(s));
    let work_tree_cli: Option<PathBuf> = matches.get_one::<String>("work-tree").map(|s| PathBuf::from(s));
    let minor = matches.get_flag("minor");
    let patch = matches.get_flag("patch");
    let subtitle_cli: Option<String> = matches.get_one::<String>("subtitle").cloned();
    let to_cli: String = matches.get_one::<String>("to").unwrap().clone();
    let outfile_cli: Option<PathBuf> = matches.get_one::<String>("outfile").map(|s| PathBuf::from(s));
    let config_cli: PathBuf = PathBuf::from(matches.get_one::<String>("config").unwrap());
    let infile_cli: Option<PathBuf> = matches.get_one::<String>("infile").map(|s| PathBuf::from(s));
    let setversion_cli: Option<String> = matches.get_one::<String>("setversion").cloned();
    let from_latest_tag_cli = matches.get_flag("from-latest-tag");
    let link_style_cli: String = matches.get_one::<String>("link-style").unwrap().clone();
    let changelog_cli: Option<PathBuf> = matches.get_one::<String>("changelog").map(|s| PathBuf::from(s));

    let work_tree_path: PathBuf = if let Some(w) = work_tree_cli.clone() {
        w
    } else if let Some(g) = git_dir_cli.clone() {
        if g.ends_with(".git") {
            g.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."))
        } else {
            PathBuf::from(".")
        }
    } else {
        PathBuf::from(".")
    };

    let git_dir_path: PathBuf = if let Some(g) = git_dir_cli.clone() {
        g
    } else if let Some(w) = work_tree_cli.clone() {
        w.join(".git")
    } else {
        PathBuf::from("./.git")
    };

    let mut config_real_path = config_cli.clone();
    if !config_real_path.is_absolute() {
        if !config_real_path.exists() {
            let alt = work_tree_path.join(&config_cli);
            if alt.exists() {
                config_real_path = alt;
            }
        }
    }

    if !config_real_path.exists() {
        eprint!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file\n");
        std::process::exit(1);
    }

    let config_content = match fs::read_to_string(&config_real_path) {
        Ok(c) => c,
        Err(_) => {
            eprint!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file\n");
            std::process::exit(1);
        }
    };

    let config_toml: toml::Value = match config_content.parse() {
        Ok(v) => v,
        Err(_) => {
            eprint!("\x1b[1;31merror:\x1b[0m Failed to parse TOML configuration file\n");
            std::process::exit(1);
        }
    };

    let clog_table = config_toml.get("clog");

    let get_clog_str = |key: &str| -> Option<String> {
        if let Some(table) = clog_table {
            if let Some(v) = table.get(key) {
                if let Some(s) = v.as_str() {
                    return Some(s.to_string());
                }
            }
        }
        None
    };

    let get_clog_bool = |key: &str| -> Option<bool> {
        if let Some(table) = clog_table {
            if let Some(v) = table.get(key) {
                if let Some(b) = v.as_bool() {
                    return Some(b);
                }
            }
        }
        None
    };

    let args: Vec<String> = std::env::args().collect();
    let has_arg = |long: &str, short: &str| -> bool {
        args.iter().any(|a| a == long || a == short || a.starts_with(&format!("{}=", long)) || a.starts_with(&format!("{}=", short)))
    };

    let mut repo_url = repository.clone();
    if repo_url.is_none() {
        if let Some(r) = get_clog_str("repository") {
            repo_url = Some(r);
        }
    }

    let mut subtitle_final = subtitle_cli.clone();
    if subtitle_final.is_none() && !has_arg("--subtitle", "-s") {
        if let Some(s) = get_clog_str("subtitle") {
            subtitle_final = Some(s);
        }
    }

    let config_changelog: Option<PathBuf> = get_clog_str("changelog").map(PathBuf::from);
    let config_from: Option<String> = get_clog_str("from");
    let config_to: Option<String> = get_clog_str("to");
    let config_from_latest_tag = get_clog_bool("from-latest-tag").unwrap_or(false);

    let mut link_style_final = LinkStyle::from_str(&link_style_cli).unwrap();
    if !has_arg("--link-style", "-l") {
        if let Some(ls_str) = get_clog_str("link-style").or_else(|| get_clog_str("link_style")) {
            if let Some(ls) = LinkStyle::from_str(&ls_str) {
                link_style_final = ls;
            }
        }
    }

    let mut format_final = format_cli.to_lowercase();
    if !has_arg("--format", "-T") {
        if let Some(f) = get_clog_str("format") {
            let f_low = f.to_lowercase();
            if f_low == "markdown" || f_low == "json" {
                format_final = f_low;
            }
        }
    }

    let mut to_final = to_cli.clone();
    if !has_arg("--to", "-t") {
        if let Some(t) = config_to.clone() {
            to_final = t;
        }
    }

    let mut from_final: Option<String> = from_cli.clone();
    if from_final.is_none() && !has_arg("--from", "-f") {
        if let Some(f) = config_from.clone() {
            from_final = Some(f);
        }
    }

    let mut from_latest_tag_final = from_latest_tag_cli;
    if !from_latest_tag_final && config_from_latest_tag {
        from_latest_tag_final = true;
    }
    if has_arg("--from", "-f") && from_final.is_some() {
        from_latest_tag_final = false;
    }

    let repo = match git2::Repository::open(&git_dir_path) {
        Ok(r) => r,
        Err(_) => {
            match git2::Repository::open(&work_tree_path) {
                Ok(r) => r,
                Err(_) => {
                    eprint!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file\n");
                    std::process::exit(1);
                }
            }
        }
    };

    let latest_tag_oid: Option<git2::Oid> = if from_latest_tag_final {
        let mut tags: Vec<(String, git2::Oid, i64)> = Vec::new();
        if let Ok(tag_names) = repo.tag_names(None) {
            for name_res in tag_names.iter() {
                if let Ok(Some(name)) = name_res {
                    if let Ok(obj) = repo.revparse_single(name) {
                        if let Ok(commit) = obj.peel_to_commit() {
                            tags.push((name.to_string(), commit.id(), commit.time().seconds()));
                        } else if let Ok(tag) = repo.find_tag(obj.id()) {
                            if let Ok(t) = tag.target() {
                                if let Ok(commit) = t.peel_to_commit() {
                                    tags.push((name.to_string(), commit.id(), commit.time().seconds()));
                                }
                            }
                        }
                    }
                }
            }
        }
        tags.sort_by(|a, b| b.2.cmp(&a.2));
        tags.first().map(|(_, oid, _)| *oid)
    } else {
        None
    };

    if from_latest_tag_final {
        if let Some(oid) = latest_tag_oid {
            from_final = Some(oid.to_string());
        } else {
            from_final = None;
        }
    }

    let to_oid = match repo.revparse_single(&to_final) {
        Ok(obj) => {
            if let Ok(commit) = obj.peel_to_commit() {
                commit.id()
            } else {
                if to_final == "HEAD" {
                    if let Ok(head) = repo.head() {
                        if let Ok(c) = head.peel_to_commit() {
                            c.id()
                        } else {
                            git2::Oid::from_str("0000000000000000000000000000000000000000").unwrap()
                        }
                    } else {
                        git2::Oid::from_str("0000000000000000000000000000000000000000").unwrap()
                    }
                } else {
                    git2::Oid::from_str("0000000000000000000000000000000000000000").unwrap()
                }
            }
        }
        Err(_) => {
            if to_final == "HEAD" {
                if let Ok(head) = repo.head() {
                    if let Ok(c) = head.peel_to_commit() {
                        c.id()
                    } else {
                        git2::Oid::from_str("0000000000000000000000000000000000000000").unwrap()
                    }
                } else {
                    git2::Oid::from_str("0000000000000000000000000000000000000000").unwrap()
                }
            } else {
                git2::Oid::from_str("0000000000000000000000000000000000000000").unwrap()
            }
        }
    };

    let from_oid_opt: Option<git2::Oid> = if let Some(from_str) = from_final.clone() {
        match repo.revparse_single(&from_str) {
            Ok(obj) => {
                if let Ok(commit) = obj.peel_to_commit() {
                    Some(commit.id())
                } else {
                    None
                }
            }
            Err(_) => None,
        }
    } else {
        None
    };

    let mut commits: Vec<ParsedCommit> = Vec::new();
    let zero_oid = git2::Oid::from_str("0000000000000000000000000000000000000000").unwrap();
    if to_oid != zero_oid {
        let mut revwalk = repo.revwalk().unwrap();
        let _ = revwalk.push(to_oid);
        if let Some(from_oid) = from_oid_opt {
            let _ = revwalk.hide(from_oid);
        }
        let _ = revwalk.set_sorting(git2::Sort::TIME);
        for oid_res in revwalk {
            if let Ok(oid) = oid_res {
                if let Ok(commit) = repo.find_commit(oid) {
                    let msg = commit.message().unwrap_or("").to_string();
                    if let Some(parsed) = parse_conventional(&msg, &oid.to_string()) {
                        commits.push(parsed);
                    }
                }
            }
        }
    }

    let mut version: Option<String> = setversion_cli.clone();
    let mut patch_version = false;

    if version.is_none() && (major || minor || patch) {
        let mut candidates: Vec<(semver::Version, String, bool)> = Vec::new();
        if let Ok(tag_names) = repo.tag_names(None) {
            for name_res in tag_names.iter() {
                if let Ok(Some(name)) = name_res {
                    let orig = name.to_string();
                    let mut t = orig.clone();
                    let had_v = t.starts_with('v') || t.starts_with('V');
                    if had_v {
                        t = t[1..].to_string();
                    }
                    if let Ok(v) = semver::Version::parse(&t) {
                        candidates.push((v, orig, had_v));
                    }
                }
            }
        }
        candidates.sort_by(|a, b| b.0.cmp(&a.0));
        if let Some((latest_ver, _orig_name, had_v)) = candidates.first() {
            let mut new_ver = latest_ver.clone();
            if major {
                new_ver.major += 1;
                new_ver.minor = 0;
                new_ver.patch = 0;
            } else if minor {
                new_ver.minor += 1;
                new_ver.patch = 0;
            } else if patch {
                new_ver.patch += 1;
            }
            let mut new_str = new_ver.to_string();
            if *had_v {
                new_str = format!("v{}", new_str);
            }
            version = Some(new_str);
            if patch {
                patch_version = true;
            }
        } else {
            eprint!("\x1b[1;31merror:\x1b[0m Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.\n");
            std::process::exit(1);
        }
    }

    let date = Local::now().format("%Y-%m-%d").to_string();

    let mut sections_map: HashMap<String, Vec<ParsedCommit>> = HashMap::new();
    let default_sections = vec![
        ("feat", "Features"),
        ("fix", "Bug Fixes"),
        ("perf", "Performance Improvements"),
        ("docs", "Documentation"),
        ("style", "Style Fixes"),
        ("refactor", "Refactor"),
        ("test", "Tests"),
        ("chore", "Chore"),
    ];
    let mut breaking_commits: Vec<ParsedCommit> = Vec::new();

    for commit in commits.iter() {
        if commit.is_breaking {
            breaking_commits.push(commit.clone());
        } else {
            for (t, title) in &default_sections {
                if commit.type_.to_lowercase() == *t {
                    sections_map.entry(title.to_string()).or_default().push(commit.clone());
                    break;
                }
            }
        }
    }

    let section_order = vec![
        "Breaking Changes",
        "Features",
        "Bug Fixes",
        "Performance Improvements",
        "Documentation",
        "Style Fixes",
        "Refactor",
        "Tests",
        "Chore",
    ];

    let mut sections_ordered: Vec<(String, Vec<ParsedCommit>)> = Vec::new();
    if !breaking_commits.is_empty() {
        sections_ordered.push(("Breaking Changes".to_string(), breaking_commits));
    }
    for title in &section_order {
        if *title == "Breaking Changes" { continue; }
        if let Some(comms) = sections_map.get(*title) {
            if !comms.is_empty() {
                sections_ordered.push((title.to_string(), comms.clone()));
            }
        }
    }
    for (title, comms) in sections_map {
        if !section_order.contains(&title.as_str()) && title != "Breaking Changes" {
            sections_ordered.push((title, comms));
        }
    }

    let new_changelog_md = generate_markdown(&version, &subtitle_final, &date, &sections_ordered, &repo_url, &link_style_final);

    let json_sections = if sections_ordered.is_empty() {
        None
    } else {
        let mut secs = Vec::new();
        for (title, comms) in &sections_ordered {
            let mut jcomms = Vec::new();
            for c in comms {
                let short = if c.hash.len() >= 8 { c.hash[..8].to_string() } else { c.hash.clone() };
                jcomms.push(JsonCommit {
                    component: c.component.clone(),
                    subject: c.subject.clone(),
                    commit_link: short,
                    closes: if c.closes.is_empty() { None } else { Some(c.closes.clone()) },
                    breaks: if c.breaks.is_empty() { None } else { Some(c.breaks.clone()) },
                });
            }
            secs.push(JsonSection { title: title.clone(), commits: jcomms });
        }
        Some(secs)
    };

    let json_output = JsonChangelog {
        header: JsonHeader {
            version: version.clone(),
            patch_version,
            subtitle: subtitle_final.clone(),
            date: date.clone(),
        },
        sections: json_sections,
    };

    let new_changelog_json = serde_json::to_string(&json_output).unwrap();

    let new_content = if format_final == "markdown" {
        new_changelog_md.clone()
    } else {
        new_changelog_json.clone()
    };

    let elapsed_ms = start.elapsed().as_millis();

    if let Some(changelog_path) = changelog_cli.clone() {
        let existing = fs::read_to_string(&changelog_path).unwrap_or_default();
        let final_content = if existing.is_empty() {
            new_content.clone()
        } else {
            format!("{}{}", new_content, existing)
        };
        if fs::write(&changelog_path, final_content).is_err() {
            eprint!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file\n");
            std::process::exit(1);
        }
        println!("changelog written. (took {} ms)", elapsed_ms);
    } else if let Some(outfile_path) = outfile_cli.clone() {
        let mut final_content = new_content.clone();
        if let Some(infile_path) = infile_cli.clone() {
            let infile_content = fs::read_to_string(&infile_path).unwrap_or_default();
            final_content = format!("{}{}", final_content, infile_content);
        }
        if fs::write(&outfile_path, final_content).is_err() {
            eprint!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file\n");
            std::process::exit(1);
        }
        println!("changelog written. (took {} ms)", elapsed_ms);
    } else {
        if let Some(cfg_changelog) = config_changelog.clone() {
            let existing = fs::read_to_string(&cfg_changelog).unwrap_or_default();
            let final_content = if existing.is_empty() {
                new_content.clone()
            } else {
                format!("{}{}", new_content, existing)
            };
            if fs::write(&cfg_changelog, final_content).is_err() {
                eprint!("\x1b[1;31merror:\x1b[0m fatal I/O error with output file\n");
                std::process::exit(1);
            }
            println!("changelog written. (took {} ms)", elapsed_ms);
            return;
        }

        let mut final_stdout = new_content.clone();
        if let Some(infile_path) = infile_cli.clone() {
            let infile_content = fs::read_to_string(&infile_path).unwrap_or_default();
            final_stdout = format!("{}{}", final_stdout, infile_content);
        }

        if format_final == "json" {
            print!("{}changelog written. (took {} ms)", final_stdout, elapsed_ms);
        } else {
            if sections_ordered.is_empty() && infile_cli.is_none() {
                let version_str = version.as_deref().unwrap_or("");
                let subtitle_str = subtitle_final.as_deref().unwrap_or("");
                let mut s = String::new();
                s.push_str(&format!("<a name=\"{}\"></a>\n", version_str));
                s.push_str(&format!("## {} {} ({})\n", version_str, subtitle_str, date));
                s.push_str("\n");
                print!("{}changelog written. (took {} ms)", s, elapsed_ms);
            } else {
                print!("{}changelog written. (took {} ms)", final_stdout, elapsed_ms);
            }
        }
    }
}

